# toychain.py: toy ledger with calls and reverts (no gas, no EVM)
import copy
from collections import namedtuple
Msg = namedtuple("Msg", "sender value")

class Revert(Exception):
    pass

class Contract:
    def __init__(self):
        self.s = {}  # storage
    def receive(self, msg):          # plain ETH arrives: accept
        pass

class Chain:
    def __init__(self):
        self.eth, self.contracts = {}, {}

    def deploy(self, addr, contract, eth=0):
        contract.addr, contract.chain = addr, self
        self.contracts[addr], self.eth[addr] = contract, eth
        return contract

    def call(self, sender, to, fn="receive", value=0, *args):
        # move value, run to.fn(msg, *args); Revert undoes all
        saved = copy.deepcopy(
            (self.eth, {a: c.s for a, c in self.contracts.items()}))
        try:
            if self.eth.get(sender, 0) < value:
                raise Revert("insufficient balance")
            self.eth[sender] = self.eth.get(sender, 0) - value
            self.eth[to] = self.eth.get(to, 0) + value
            target = self.contracts.get(to)
            if target is None:       # plain account: no code runs
                return True
            return getattr(target, fn)(Msg(sender, value), *args)
        except Revert:
            self.eth = saved[0]
            for a, storage in saved[1].items():
                self.contracts[a].s = storage
            raise

    def try_call(self, *a):          # low-level call style
        try:
            self.call(*a); return True
        except Revert:
            return False

from toychain import Chain, Contract, Revert

class Bank(Contract):
    def __init__(self):
        self.s = {"bal": {}}
    def deposit(self, msg):
        b = self.s["bal"]
        b[msg.sender] = b.get(msg.sender, 0) + msg.value
    def withdraw(self, msg, amount):
        if self.s["bal"].get(msg.sender, 0) < amount:   # check
            raise Revert("not enough deposited")
        self.s["bal"][msg.sender] -= amount               # effect
        self.chain.call(self.addr, msg.sender, "receive", amount)  # interaction

def solvent(chain, bank):        # the invariant: ETH held >= ETH owed
    return chain.eth[bank.addr] >= sum(bank.s["bal"].values())

