class VulnerableBank(Contract):
    def __init__(self):
        self.s = {"bal": {}}
    def deposit(self, msg):
        self.s["bal"][msg.sender] = self.s["bal"].get(msg.sender, 0) + msg.value
    def withdraw(self, msg):
