    def withdraw(self, msg):
        amount = self.s["bal"].get(msg.sender, 0)
        if amount == 0:                                            # checks
            raise Revert("nothing to withdraw")
        self.s["bal"][msg.sender] = 0                              # effects
        self.chain.call(self.addr, msg.sender, "receive", amount)  # interactions

