from toychain import Chain, Contract, Revert

class PushAuction(Contract):      # refunds old leader inside bid()
    def __init__(self):
        self.s = {"leader": None, "top": 0, "owed": {}}
    def bid(self, msg):
        if msg.value <= self.s["top"]:
            raise Revert("bid too low")
        if self.s["leader"]:          # if this refund fails, bid() fails
            self.chain.call(self.addr, self.s["leader"], "receive", self.s["top"])
        self.s["leader"], self.s["top"] = msg.sender, msg.value

class PullAuction(PushAuction):   # records refund; leader pulls it
    def bid(self, msg):
        if msg.value <= self.s["top"]:
            raise Revert("bid too low")
        if self.s["leader"]:
            owed = self.s["owed"]
            owed[self.s["leader"]] = owed.get(self.s["leader"], 0) + self.s["top"]
        self.s["leader"], self.s["top"] = msg.sender, msg.value
    def withdraw(self, msg):
        amount = self.s["owed"].pop(msg.sender, 0)
        self.chain.call(self.addr, msg.sender, "receive", amount)

class Refuser(Contract):          # receive always reverts
    def receive(self, msg):
        raise Revert("I refuse ETH")

for A in (PushAuction, PullAuction):
    chain = Chain()
    chain.eth.update({"bo": 50})
    a = chain.deploy("auction", A())
    chain.deploy("refuser", Refuser(), eth=50)
    chain.call("refuser", "auction", "bid", 10)
    try:
        chain.call("bo", "auction", "bid", 20)
    except Revert as e:
        print(A.__name__, "Bo's higher bid reverted:", e)
    print(A.__name__, "leader:", a.s["leader"], "top:", a.s["top"])

