pragma solidity ^0.8.24;

contract AuctionPull {
    address public leader;
    uint256 public top;
    mapping(address => uint256) public owed;

    function bid() external payable {
        require(msg.value > top, "bid too low");
        if (leader != address(0)) owed[leader] += top;  // record, do not send
        leader = msg.sender;
        top = msg.value;
    }

    function withdraw() external {
        uint256 amount = owed[msg.sender];
        owed[msg.sender] = 0;
        (bool ok, ) = payable(msg.sender).call{value: amount}("");
        require(ok, "transfer failed");                 // never ignore the result
    }
}

from toychain import Chain, Contract, Revert

class FlashLender(Contract):
    def flash_loan(self, msg, amount, fee):
        before = self.chain.eth[self.addr]
        self.chain.call(self.addr, msg.sender, "on_loan", amount)  # lend
        if self.chain.eth[self.addr] < before + fee:               # repaid?
            raise Revert("loan not repaid: whole transaction undone")

class Borrower(Contract):
    def __init__(self, repay):
        self.s = {"repay": repay}
    def on_loan(self, msg):
        # ... the borrowed ETH could be used here for anything ...
        if self.s["repay"]:
            self.chain.call(self.addr, msg.sender, "receive", msg.value + 1)

for repay in (True, False):
    chain = Chain()
    chain.deploy("lender", FlashLender(), eth=1_000)
    chain.deploy("b", Borrower(repay), eth=5)
    try:
        chain.call("b", "lender", "flash_loan", 0, 1_000, 1)
        print("repaid:  ", chain.eth)
    except Revert as e:
        print("reverted:", e, chain.eth)

