pragma solidity ^0.8.24;

interface IPair { function getReserves() external view returns (uint112, uint112, uint32); }
interface AggregatorV3Interface {
    function latestRoundData() external view returns (
        uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound);
}

contract PriceReader {
    IPair public pair;
    AggregatorV3Interface public feed;
    uint256 public constant MAX_AGE = 1 hours;

    // UNSAFE: spot price from one pool, movable inside a single transaction
    function spotPrice() public view returns (uint256) {
        (uint112 ethReserve, uint112 usdReserve, ) = pair.getReserves();
        return uint256(usdReserve) * 1e18 / ethReserve;
    }

    // SAFER: aggregated off-chain feed, with sanity and staleness checks
    function feedPrice() public view returns (uint256) {
        (, int256 answer, , uint256 updatedAt, ) = feed.latestRoundData();
        require(answer > 0, "bad price");
        require(block.timestamp - updatedAt <= MAX_AGE, "stale price");
        return uint256(answer);
    }
}

