// FIXED: commit a hash first, reveal after the deadline
contract CommitReveal {
    mapping(address => bytes32) public commitOf;
    mapping(address => uint256) public answerOf;
    uint256 public immutable commitDeadline;
    uint256 public immutable revealDeadline;

    constructor(uint256 commitSecs, uint256 revealSecs) {
        commitDeadline = block.timestamp + commitSecs;
        revealDeadline = commitDeadline + revealSecs;
    }
    function commit(bytes32 c) external {
        require(block.timestamp < commitDeadline, "commit phase over");
        commitOf[msg.sender] = c;
    }
    function reveal(uint256 answer, bytes32 salt) external {
        require(block.timestamp >= commitDeadline && block.timestamp < revealDeadline, "not reveal phase");
        require(keccak256(abi.encode(answer, salt, msg.sender)) == commitOf[msg.sender], "mismatch");
        answerOf[msg.sender] = answer;
    }
}

