pragma solidity ^0.8.24;

contract VoucherVault {
    address public immutable signer;
    mapping(uint256 => bool) public used;
    bytes32 private constant VOUCHER_TYPEHASH =
        keccak256("Voucher(address to,uint256 amount,uint256 nonce,uint256 deadline)");
    bytes32 public immutable DOMAIN_SEPARATOR;

    constructor(address _signer) payable {
        signer = _signer;
        DOMAIN_SEPARATOR = keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256("VoucherVault"), keccak256("1"), block.chainid, address(this)));
    }

    function redeem(address to, uint256 amount, uint256 nonce, uint256 deadline,
                    uint8 v, bytes32 r, bytes32 s) external {
        require(block.timestamp <= deadline, "expired");
        require(!used[nonce], "nonce used");
        bytes32 structHash = keccak256(abi.encode(VOUCHER_TYPEHASH, to, amount, nonce, deadline));
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, structHash));
        address who = ecrecover(digest, v, r, s);
        require(who != address(0) && who == signer, "bad signature");
        used[nonce] = true;                          // effect before interaction
        (bool ok, ) = payable(to).call{value: amount}("");
        require(ok, "transfer failed");
    }
}

import hashlib, json
from ecdsa import SigningKey, SECP256k1, BadSignatureError

key = SigningKey.generate(curve=SECP256k1)  # Ana's key
ANA = key.get_verifying_key()
def digest(obj):                    # toy stand-in for EIP-712 hashing
    return hashlib.sha256(json.dumps(obj, sort_keys=True).encode()).digest()
def sign(obj):
    return key.sign_digest_deterministic(digest(obj), hashfunc=hashlib.sha256)

class NaiveVault:          # pays any voucher Ana signed
    def __init__(self, chain_id):
        self.domain = {"chainId": chain_id, "contract": "vault"}
        self.paid, self.used = 0, set()
    def redeem(self, v, sig):
        ANA.verify_digest(sig, digest(v))
        self.paid += v["amount"]

class SafeVault(NaiveVault):  # domain, nonce, deadline
    def redeem(self, v, sig, now=100):
        ANA.verify_digest(sig, digest({"domain": self.domain, **v}))
        if v["nonce"] in self.used: raise ValueError("nonce used")
        if now > v["deadline"]: raise ValueError("expired")
        self.used.add(v["nonce"])
        self.paid += v["amount"]

v = {"to": "bo", "amount": 10, "nonce": 1, "deadline": 200}
dom = {"chainId": 1, "contract": "vault"}
for V, sig in ((NaiveVault, sign(v)), (SafeVault, sign({"domain": dom, **v}))):
    home, other = V(1), V(10)       # same code on a 2nd chain
    for target in (home, home, other):
        try:
            target.redeem(v, sig)
        except (BadSignatureError, ValueError) as e:
            print(f"{V.__name__}: rejected, {type(e).__name__}: {e}")
    print(f"{V.__name__}: paid home={home.paid} other={other.paid}")

EIP1967_SLOT = "0x3608...2bbc"   # keccak256("eip1967.proxy.implementation") - 1

class Proxy:
    def __init__(self, impl_slot, impl):
        self.storage = {impl_slot: impl}
        self.impl_slot = impl_slot
    def fallback(self, fn, *args):      # delegatecall: impl code, proxy storage
        code = self.storage[self.impl_slot]
        return code[fn](self.storage, *args)

# Logic contract compiled with its first variable `owner` at slot 0
TokenV1 = {"set_owner": lambda st, who: st.__setitem__(0, who),
           "owner":     lambda st: st.get(0)}

for slot in (0, EIP1967_SLOT):
    p = Proxy(slot, TokenV1)
    p.fallback("set_owner", "ana")
    impl = p.storage[p.impl_slot]
    print(f"impl slot {slot!s:14} -> implementation now:",
          "TokenV1" if impl is TokenV1 else repr(impl))

# Independent check a signer runs BEFORE approving a multisig transaction.
# It decodes the raw fields itself instead of trusting what a web page shows.
KNOWN_TARGETS = {"hot_wallet", "usdc_token"}       # our own allowlist
SELECTORS = {"a9059cbb": "transfer(address,uint256)"}

def review(tx):
    problems = []
    if tx["operation"] != 0:                       # 0 = CALL, 1 = DELEGATECALL
        problems.append("DELEGATECALL: target code will run AS the wallet")
    if tx["to"] not in KNOWN_TARGETS:
        problems.append(f"unknown target {tx['to']}")
    selector = tx["data"][:8]
    if tx["data"] and selector not in SELECTORS:
        problems.append(f"unknown function selector {selector}")
    return problems or ["looks like a routine transfer"]

routine = {"to": "hot_wallet", "operation": 0, "value": 500, "data": ""}
tampered = {"to": "unverified_contract", "operation": 1, "value": 0,
            "data": "a9059cbb" + "00" * 64}      # LOOKS like transfer(...)
for name, tx in (("routine", routine), ("tampered", tampered)):
    print(name + ":", review(tx))

# Toy lending account: collateral and debt in USD. Liquidation allowed when
# health = collateral * 0.9 / debt < 1. (Simplified: Euler V1 was far richer.)
def health(acct):
    return acct["collateral"] * 0.9 / acct["debt"]

def donate(acct, amount, check_health):
    acct["collateral"] -= amount                 # gift to the protocol's reserves
    if check_health and health(acct) < 1:        # the line the fix adds
        raise ValueError(f"donation would make health {health(acct):.2f} < 1: revert")

for check in (False, True):
    acct = {"collateral": 1_200, "debt": 1_000}
    try:
        donate(acct, 300, check)
        print(f"check={check}: health now {health(acct):.2f}, liquidatable: {health(acct) < 1}")
    except ValueError as e:
        print(f"check={check}:", e)

import random
from toychain import Chain, Revert
from banks import VulnerableBank, SafeBank, Reenterer

def solvent(chain, bank):
    return chain.eth["bank"] >= sum(bank.s["bal"].values())

def fuzz(Bank, runs=200, steps=8, seed=1):
    rng = random.Random(seed)                  # fixed seed: reproducible
    for run in range(runs):
        chain = Chain()
        chain.eth.update({"ana": 20, "bo": 20})
        bank = chain.deploy("bank", Bank())
        chain.deploy("r", Reenterer(), eth=20)
        history = []
        for _ in range(steps):
            who = rng.choice(["ana", "bo", "r"])
            if rng.random() < 0.5:
                action = (who, "deposit", rng.randint(1, 5))
            else:
                action = (who, "withdraw", 0)
            history.append(action)
            try:
                chain.call(action[0], "bank", action[1], action[2])
            except Revert:
                pass                           # a revert is allowed
            if not solvent(chain, bank):       # the invariant must always hold
                return f"run {run}: BROKEN after {history}"
    return f"{runs} runs x {steps} steps: invariant held"

print("VulnerableBank:", fuzz(VulnerableBank))
print("SafeBank:      ", fuzz(SafeBank))

from toychain import Chain, Contract, Revert

class Bridge(Contract):             # buggy: releases 10 for ANY message
    def __init__(self):
        self.s = {"paused": False, "locked": 100}   # 'locked' = deposits backing it
    def release(self, msg):
        if self.s["paused"]:
            raise Revert("paused")
        self.chain.call(self.addr, msg.sender, "receive", 10)   # no proof checked
    def pause(self, msg):
        if msg.sender != "guardian":                 # small, separate role
            raise Revert("not guardian")
        self.s["paused"] = True

def run(monitoring):
    chain = Chain()
    bridge = chain.deploy("bridge", Bridge(), eth=100)
    for caller in ["x1", "x2", "x3", "x4", "x5", "x6"]:
        chain.try_call(caller, "bridge", "release")  # copycats, one per block
        if monitoring and chain.eth["bridge"] < bridge.s["locked"]:
            chain.try_call("guardian", "bridge", "pause")   # alert, then pause
    return 100 - chain.eth["bridge"]

print("lost without monitoring:", run(False))
print("lost with invariant monitor + pause:", run(True))
